import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.CNDaxUod.js";const h=JSON.parse('{"title":"Account and cloud sync","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cloud-sync.md","filePath":"guide/cloud-sync.md","lastUpdated":1788607300000}'),s={name:"guide/cloud-sync.md"};function i(r,e,d,c,l,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="account-and-cloud-sync" tabindex="-1">Account and cloud sync <a class="header-anchor" href="#account-and-cloud-sync" aria-label="Permalink to &quot;Account and cloud sync&quot;">​</a></h1><p>Web Resume remains local-first: editing, preview, and PDF export work without an account. On the main site, you can optionally sign in with a YunLeFun account and save portable YAML resumes in your YunLeFun Drive storage space.</p><h2 id="first-save-and-autosave" tabindex="-1">First save and autosave <a class="header-anchor" href="#first-save-and-autosave" aria-label="Permalink to &quot;First save and autosave&quot;">​</a></h2><ol><li>Open <strong>Profile</strong> from the side or bottom navigation.</li><li>Sign in with YunLeFun.</li><li>Give the current resume a file name and choose <strong>Create and save</strong>.</li><li>After that first save, changes sync about two seconds after you stop typing.</li></ol><p>Invalid YAML drafts are still saved and marked as needing fixes. The cloud file contains the original portable YAML and required metadata; local profile overrides such as your name, phone, and email are not included.</p><h2 id="multiple-devices-and-conflicts" tabindex="-1">Multiple devices and conflicts <a class="header-anchor" href="#multiple-devices-and-conflicts" aria-label="Permalink to &quot;Multiple devices and conflicts&quot;">​</a></h2><p>Open any file in the <strong>Web Resume</strong> section of Profile or the resume source dialog. Web Resume uses optimistic versions. If another device has already saved a newer version, your edit is preserved as a conflict copy instead of overwriting the newer file.</p><h2 id="storage-trash-and-sign-out" tabindex="-1">Storage, Trash, and sign-out <a class="header-anchor" href="#storage-trash-and-sign-out" aria-label="Permalink to &quot;Storage, Trash, and sign-out&quot;">​</a></h2><p>Cloud resumes use your shared YunLeFun Drive quota. Moving a resume to Trash keeps it recoverable for 30 days. Signing out leaves local editor content and profile fields on the device. <strong>Clear device data</strong> removes Web Resume data from the current browser only; it does not delete cloud files.</p><p>Cloud resumes are private and have no public sharing link. Storage is not end-to-end encrypted, so do not put passwords, API keys, or access tokens in a resume.</p><p>GitHub is not an automatic sync provider. A future integration may offer explicit import and export without making GitHub the source of truth.</p>',11)])])}const f=a(s,[["render",i]]);export{h as __pageData,f as default};
